    '55555555-0000-0000-0000-000000000001','55555555-0000-0000-0000-000000000002',
    '55555555-0000-0000-0000-000000000003','55555555-0000-0000-0000-000000000004',
    '55555555-0000-0000-0000-000000000005','55555555-0000-0000-0000-000000000006',
    '55555555-0000-0000-0000-000000000007');
DELETE FROM variants WHERE product_id IN (
    '44444444-0000-0000-0000-000000000001','44444444-0000-0000-0000-000000000002',
    '44444444-0000-0000-0000-000000000003','44444444-0000-0000-0000-000000000004',
    '44444444-0000-0000-0000-000000000005','44444444-0000-0000-0000-000000000006');
DELETE FROM products WHERE id IN (
    '44444444-0000-0000-0000-000000000001','44444444-0000-0000-0000-000000000002',
    '44444444-0000-0000-0000-000000000003','44444444-0000-0000-0000-000000000004',
    '44444444-0000-0000-0000-000000000005','44444444-0000-0000-0000-000000000006');
